        assertThat(timed.request().rollbackCause()).isEqualTo("CRITICAL_TIMEOUT");

        var steps = repo.listSteps("R-T");
        assertThat(steps).filteredOn(s -> s.getStatus().equals("FROZEN")).hasSize(1); // seq4 冻结
