                .extracting(e -> e.eventType()).contains("ROLLBACK_TRIGGER");

        // 冻结后继续回报后续步骤 -> 拒绝
        assertThatThrownBy(() -> service.report(report("t-r4", "R-T", 4, true, BASE.plusMinutes(21))))
                .isInstanceOf(BusinessRuleException.class)
                .hasMessageContaining("冻结");
    }

    @Test
